class Solution {
public:
    bool isPalindromic(string s) {
        int total = (int)s.size() * 8;
        for (int left = 0, right = total - 1; left < right; ++left, --right) {
            int a = (static_cast<unsigned char>(s[left / 8]) >> (7 - left % 8)) & 1;
            int b = (static_cast<unsigned char>(s[right / 8]) >> (7 - right % 8)) & 1;
            if (a != b) return false;
        }
        return true;
    }
};
